class MyCalendar {
    private final java.util.TreeMap<Integer, Integer> intervals = new java.util.TreeMap<>();

    public MyCalendar() {
    }

    public boolean book(int start, int end) {
        Integer previousStart = intervals.floorKey(start);
        if (previousStart != null && intervals.get(previousStart) > start) {
            return false;
        }

        Integer nextStart = intervals.ceilingKey(start);
        if (nextStart != null && nextStart < end) {
            return false;
        }

        intervals.put(start, end);
        return true;
    }
}

