class MyCalendar {
    private final List<int[]> events = new ArrayList<>();

    public MyCalendar() {
    }

    public boolean book(int start, int end) {
        for (int[] event : events) {
            if (start < event[1] && event[0] < end) {
                return false;
            }
        }
        events.add(new int[] {start, end});
        return true;
    }
