import java.util.*;

class MyCalendar {
    private final ArrayList<Integer> starts = new ArrayList<>();
    private final ArrayList<Integer> ends = new ArrayList<>();

    public MyCalendar() {
    }

    public boolean book(int start, int end) {
        int index = Collections.binarySearch(starts, start);
        if (index < 0) {
            index = -index - 1;
        }

        if (index > 0 && ends.get(index - 1) > start) {
            return false;
        }
        if (index < starts.size() && starts.get(index) < end) {
            return false;
        }

        starts.add(index, start);
        ends.add(index, end);
        return true;
    }
}

class MyCalendar {
    private final java.util.TreeMap<Integer, Integer> delta = new java.util.TreeMap<>();

    public MyCalendar() {
    }

    public boolean book(int start, int end) {
        addDelta(start, 1);
        addDelta(end, -1);

        int active = 0;
        for (int change : delta.values()) {
            active += change;
            if (active > 1) {
                addDelta(start, -1);
                addDelta(end, 1);
                return false;
            }
        }
        return true;
    }

    private void addDelta(int time, int change) {
        int next = delta.getOrDefault(time, 0) + change;
        if (next == 0) {
            delta.remove(time);
        } else {
            delta.put(time, next);
        }
    }
}

class MyCalendar {
    private static class Node {
        Node left;
        Node right;
        int add;
        int max;
    }

    private final Node root = new Node();

    public MyCalendar() {
    }

    public boolean book(int start, int end) {
        int left = start;
        int right = end - 1;
        if (query(root, 0, 1_000_000_000, left, right, 0) > 0) {
            return false;
        }
        update(root, 0, 1_000_000_000, left, right, 1);
        return true;
    }

    private void update(Node node, int left, int right, int ql, int qr, int delta) {
        if (ql <= left && right <= qr) {
            node.add += delta;
            node.max += delta;
            return;
        }

        int mid = left + (right - left) / 2;
        if (ql <= mid) {
            if (node.left == null) {
                node.left = new Node();
            }
            update(node.left, left, mid, ql, qr, delta);
        }
        if (qr > mid) {
            if (node.right == null) {
                node.right = new Node();
            }
            update(node.right, mid + 1, right, ql, qr, delta);
        }

        int leftMax = node.left == null ? 0 : node.left.max;
        int rightMax = node.right == null ? 0 : node.right.max;
        node.max = node.add + Math.max(leftMax, rightMax);
    }

    private int query(Node node, int left, int right, int ql, int qr, int carry) {
        if (qr < left || right < ql) {
            return 0;
        }
        if (node == null) {
            return carry;
        }
        if (ql <= left && right <= qr) {
            return carry + node.max;
        }

        int mid = left + (right - left) / 2;
        int nextCarry = carry + node.add;
        return Math.max(
                query(node.left, left, mid, ql, qr, nextCarry),
                query(node.right, mid + 1, right, ql, qr, nextCarry));
    }
}
